process {

    withName: GATK4_MARKDUPLICATES {
        ext.args   = '--CREATE_INDEX true'
        ext.prefix = { "${meta.id}.bam" }
    }
}

process {

    withName: GATK4_MARKDUPLICATES {
        ext.args   = '--CREATE_INDEX true'
        ext.prefix = { "${meta.id}.cram" }
    }
}

nextflow_process {

    name "Test Process GATK4_MARKDUPLICATES"
    script "../main.nf"
    process "GATK4_MARKDUPLICATES"

    tag "modules"
    tag "modules_nfcore"
    tag "gatk4"
    tag "gatk4/markduplicates"

    test("sarscov2 - bam") {
        config "./bam.config"

        when {
            process {
                """
                input[0] = [
                    [ id:'test', single_end:false ],
                    file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/bam/test.paired_end.sorted.bam', checkIfExists: true)
                ]
                input[1] = []
                input[2] = []
                """
            }
        }

        then {
            assert process.success
            assertAll(
                { assert snapshot(
                    sanitizeOutput(process.out, readsMD5Keys: ["bam"], unstableKeys: ["bai", "metrics"])
                ).match() }
            )
        }
    }

    test("homo_sapiens - multiple bam") {
        config "./bam.config"

        when {
            process {
                """
                input[0] = [
                    [ id:'test', single_end:false ],
                    [
                        file(params.modules_testdata_base_path + 'genomics/homo_sapiens/illumina/bam/test.paired_end.sorted.bam', checkIfExists: true),
                        file(params.modules_testdata_base_path + 'genomics/homo_sapiens/illumina/bam/test2.paired_end.sorted.bam', checkIfExists: true)
                    ]
                ]
                input[1] = []
                input[2] = []
                """
            }
        }

        then {
            assert process.success
            assertAll(
                { assert snapshot(
                    sanitizeOutput(process.out, readsMD5Keys: ["bam"], unstableKeys: ["bai", "metrics"])
                ).match() }
            )
        }
    }

    test("homo_sapiens - multiple cram") {
        config "./cram.config"

        when {
            process {
                """
                input[0] = [
                    [ id:'test', single_end:false ], // meta map
                    [
                        file(params.modules_testdata_base_path + 'genomics/homo_sapiens/illumina/bam/test.paired_end.sorted.bam', checkIfExists: true),
                        file(params.modules_testdata_base_path + 'genomics/homo_sapiens/illumina/bam/test2.paired_end.sorted.bam', checkIfExists: true)
                    ]
                ]
                input[1] = file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/genome.fasta', checkIfExists: true)
                input[2] = file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/genome.fasta.fai', checkIfExists: true)
                """
            }
        }

        then {
            def fasta = 'https://raw.githubusercontent.com/nf-core/test-datasets/modules/data/genomics/homo_sapiens/genome/genome.fasta'
            assert process.success
            assertAll(
                { assert snapshot(
                    sanitizeOutput(process.out, readsMD5Keys: ["cram"], unstableKeys: ["crai", "metrics"], referenceFasta: fasta)
                ).match() }
            )
        }
    }

    test("stub") {
        config "./bam.config"
        options "-stub"

        when {
            process {
                """
                input[0] = [
                    [ id:'test', single_end:false ],
                    []
                ]
                input[1] = []
                input[2] = []
                """
            }
        }

        then {
            assert process.success
            assertAll(
                { assert snapshot(sanitizeOutput(process.out)).match() }
            )
        }
    }
}

